using namespace sol;

SOL_TEST(base64DecodesKnownVectors)
{
    std::vector<std::uint8_t> out;
    SOL_CHECK(cooker::decodeBase64("aGVsbG8=", 8, out));
    SOL_CHECK(out.size() == 5 && std::memcmp(out.data(), "hello", 5) == 0);
    SOL_CHECK(cooker::decodeBase64("", 0, out) && out.empty());
    SOL_CHECK(!cooker::decodeBase64("a!b", 3, out));
}

SOL_TEST(pngDecodesRgba2x2)
{
    // 2x2 RGBA PNG generated by System.Drawing:
    // (0,0) red, (1,0) green, (0,1) blue, (1,1) white with alpha 128.
    static const std::uint8_t kPng[] = {
        0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0x00, 0x00, 0x00, 0x0d, 0x49, 0x48, 0x44,
        0x52, 0x00, 0x00, 0x00, 0x02, 0x00, 0x00, 0x00, 0x02, 0x08, 0x06, 0x00, 0x00, 0x00, 0x72,
        0xb6, 0x0d, 0x24, 0x00, 0x00, 0x00, 0x01, 0x73, 0x52, 0x47, 0x42, 0x00, 0xae, 0xce, 0x1c,
        0xe9, 0x00, 0x00, 0x00, 0x04, 0x67, 0x41, 0x4d, 0x41, 0x00, 0x00, 0xb1, 0x8f, 0x0b, 0xfc,
        0x61, 0x05, 0x00, 0x00, 0x00, 0x09, 0x70, 0x48, 0x59, 0x73, 0x00, 0x00, 0x0e, 0xc3, 0x00,
        0x00, 0x0e, 0xc3, 0x01, 0xc7, 0x6f, 0xa8, 0x64, 0x00, 0x00, 0x00, 0x14, 0x49, 0x44, 0x41,
        0x54, 0x18, 0x57, 0x63, 0xf8, 0xcf, 0xc0, 0xf0, 0x1f, 0x0c, 0x19, 0x18, 0xfe, 0x83, 0x40,
        0x03, 0x00, 0x49, 0x49, 0x09, 0x78, 0xce, 0xd7, 0x63, 0xf7, 0x00, 0x00, 0x00, 0x00, 0x49,
        0x45, 0x4e, 0x44, 0xae, 0x42, 0x60, 0x82};

    cooker::ImageRgba image;
    SOL_CHECK(cooker::decodePng(kPng, sizeof(kPng), image));
    SOL_CHECK(image.width == 2 && image.height == 2);
    SOL_CHECK(image.pixels.size() == 16);

    const std::uint8_t* p = image.pixels.data();
    SOL_CHECK(p[0] == 255 && p[1] == 0 && p[2] == 0 && p[3] == 255);     // red
    SOL_CHECK(p[4] == 0 && p[5] == 255 && p[6] == 0 && p[7] == 255);     // green
    SOL_CHECK(p[8] == 0 && p[9] == 0 && p[10] == 255 && p[11] == 255);   // blue
    SOL_CHECK(p[12] == 255 && p[13] == 255 && p[14] == 255 && p[15] == 128); // white, half alpha
}

SOL_TEST(pngRejectsGarbage)
{
    cooker::ImageRgba image;
    const std::uint8_t junk[64] = {1, 2, 3};
    SOL_CHECK(!cooker::decodePng(junk, sizeof(junk), image));
}

SOL_TEST(bc1EncodesSolidBlockExactly)
{
    cooker::ImageRgba image;
    image.width = 4;
    image.height = 4;
    image.pixels.assign(64, 0);
    for (std::size_t i = 0; i < 16; ++i) {
        image.pixels[i * 4 + 0] = 255; // pure red
        image.pixels[i * 4 + 3] = 255;
    }

    const std::vector<std::uint8_t> blocks = cooker::encodeBc1(image);
    SOL_CHECK(blocks.size() == 8);
    // Both endpoints equal pure red in RGB565 (0xF800); all indices select c0.
    SOL_CHECK(blocks[0] == 0x00 && blocks[1] == 0xF8);
    SOL_CHECK(blocks[2] == 0x00 && blocks[3] == 0xF8);
    SOL_CHECK(blocks[4] == 0 && blocks[5] == 0 && blocks[6] == 0 && blocks[7] == 0);
}

SOL_TEST(bc1OutputSizeMatchesBlockCount)
{
    cooker::ImageRgba image;
    image.width = 6; // 2 blocks wide (rounded up)
    image.height = 10; // 3 blocks tall
    image.pixels.assign(static_cast<std::size_t>(image.width) * image.height * 4, 200);
    SOL_CHECK(cooker::encodeBc1(image).size() == 2u * 3u * 8u);
}

SOL_TEST(downsampleHalfAverages)
{
    cooker::ImageRgba image;
    image.width = 2;
    image.height = 2;
    image.pixels = {0, 0, 0, 255, 100, 0, 0, 255, 0, 200, 0, 255, 0, 0, 100, 255};
    const cooker::ImageRgba half = cooker::downsampleHalf(image);
    SOL_CHECK(half.width == 1 && half.height == 1);
    SOL_CHECK(half.pixels[0] == 25 && half.pixels[1] == 50 && half.pixels[2] == 25 &&
              half.pixels[3] == 255);
}

SOL_TEST(gltfImportsTriangleWithNodeTransform)
{
    // Triangle at (0,0,0) (1,0,0) (0,1,0), u16 indices, node translated +10 X.
    const char* gltf = R"({
        "asset": {"version": "2.0"},
        "scene": 0,
        "scenes": [{"nodes": [0]}],
        "nodes": [{"mesh": 0, "translation": [10, 0, 0]}],
        "meshes": [{"primitives": [{"attributes": {"POSITION": 0}, "indices": 1}]}],
        "buffers": [{"byteLength": 42, "uri":
            "data:application/octet-stream;base64,AAAAAAAAAAAAAAAAAACAPwAAAAAAAAAAAAAAAAAAgD8AAAAAAAABAAIA"}],
        "bufferViews": [
            {"buffer": 0, "byteOffset": 0, "byteLength": 36},
            {"buffer": 0, "byteOffset": 36, "byteLength": 6}
        ],
        "accessors": [
            {"bufferView": 0, "componentType": 5126, "count": 3, "type": "VEC3"},
            {"bufferView": 1, "componentType": 5123, "count": 3, "type": "SCALAR"}
        ]
    })";

    const std::string path = std::string(platform::executableDirectory()) + "test_triangle.gltf";
    SOL_CHECK(platform::writeFileBytes(path.c_str(), gltf, std::strlen(gltf)));

    assets::MeshData mesh;
    SOL_CHECK(cooker::importGltf(path.c_str(), mesh));
    SOL_CHECK(mesh.vertices.size() == 3);
    SOL_CHECK(mesh.indices.size() == 3);
    SOL_CHECK(mesh.indices[0] == 0 && mesh.indices[1] == 1 && mesh.indices[2] == 2);
    // Node translation baked into positions.
    SOL_CHECK(mesh.vertices[0].position[0] == 10.0f);
    SOL_CHECK(mesh.vertices[1].position[0] == 11.0f);
    SOL_CHECK(mesh.vertices[2].position[1] == 1.0f);

    std::remove(path.c_str());
}
